parameters.jsCode:
const fs = require('fs');

const archivos = [
  '/home/Tlsg_n8n/registro_datos.csv',
  '/home/Tlsg_n8n/registro_datos_ingresados_cliente.csv'
];

const ocr = $('OCR_ParsearJSON').first().json;

function normalizarNumero(valor) {
  return String(valor || '')
    .trim()
    .replace(/[\s\-\.]/g, '')
    .replace(/^0+(?=\d)/, '')
    .toUpperCase();
}

const transaccion = normalizarNumero(ocr.numero_transaccion);

function parseCsvLine(linea) {
  const campos = [];
  let actual = '';
  let entreComillas = false;

  for (let i = 0; i < linea.length; i++) {
    const char = linea[i];
    if (char === '"') {
      if (entreComillas && linea[i + 1] === '"') {
        actual += '"';
        i++;
      } else {
        entreComillas = !entreComillas;
      }
    } else if (char === ',' && !entreComillas) {
      campos.push(actual);
      actual = '';
    } else {
      actual += char;
    }
  }
  campos.push(actual);
  return campos;
}

// IMPORTANTE: el indice se reconstruye SIEMPRE en cada ejecucion, leyendo
// los archivos directamente del disco. Anteriormente se cacheaba en
// $getWorkflowStaticData('global') usando una firma de tamano/mtime del
// archivo; como el static data es compartido entre ejecuciones concurrentes
// del workflow, dos comprobantes que llegan casi al mismo tiempo podian leer
// una copia obsoleta del indice (uno todavia sin el registro que el otro
// acababa de escribir), dejando pasar duplicados reales. Leer siempre en
// caliente elimina esa condicion de carrera; el costo extra de I/O es
// insignificante frente al riesgo de aceptar comprobantes duplicados.
function construirIndice() {
  const indice = {};

  for (const archivo of archivos) {
    if (!fs.existsSync(archivo)) continue;

    const lineas = fs.readFileSync(archivo, 'utf8').split(/\r?\n/);
    for (let i = 1; i < lineas.length; i++) {
      if (!lineas[i].trim()) continue;
      const columnas = parseCsvLine(lineas[i]);
      const numero = normalizarNumero(columnas[8]);
      if (!numero) continue;

      // Si el mismo numero aparece en ambos archivos, nos quedamos con el
      // registro mas reciente (ultima linea leida) en vez del primero.
      indice[numero] = {
        archivo,
        linea: i + 1,
        whatsapp: columnas[2] || '',
        fecha: columnas[0] || '',
        banco: columnas[5] || '',
        monto: columnas[6] || '',
        numero_transaccion: columnas[8] || '',
        titular: columnas[9] || ''
      };
    }
  }

  return indice;
}

const indiceTransacciones = construirIndice();

const detalle = transaccion
  ? (indiceTransacciones[transaccion] || null)
  : null;

return [{
  json: {
    ...ocr,
    duplicado: Boolean(detalle),
    detalle,
    numero_transaccion_vacio: transaccion === ''
  }
}];

