const inputItem = $input.item;
const item = inputItem?.json || {};
const binary = inputItem?.binary;

function limpiarBloques(texto) {
  return String(texto)
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

function extraerTexto(obj) {
  return (
    obj?.['0']?.content?.[0]?.text ??
    obj?.[0]?.content?.[0]?.text ??
    obj?.content?.[0]?.text ??
    obj?.output?.[0]?.content?.[0]?.text ??
    obj?.output_text ??
    obj?.text ??
    null
  );
}

let data;
const opcionActual = Number(item.opcion);

// OCR_PrepararDatosParaSwitch ya convirtió la respuesta del modelo.
if ([0, 1, 2].includes(opcionActual)) {
  data = { ...item, opcion: opcionActual };
} else {
  const textoCrudo = extraerTexto(item);
  if (!textoCrudo) {
    throw new Error(
      'No se encontró texto OCR ni un objeto OCR previamente parseado. ' +
      'Estructura recibida: ' + JSON.stringify(item)
    );
  }

  const text = limpiarBloques(textoCrudo);
  const inicio = text.indexOf('{');
  const fin = text.lastIndexOf('}');
  if (inicio === -1 || fin === -1 || fin < inicio) {
    throw new Error('La respuesta OCR no contiene un objeto JSON válido: ' + text);
  }

  try {
    data = { ...item, ...JSON.parse(text.slice(inicio, fin + 1)) };
  } catch (error) {
    throw new Error(
      'No se pudo interpretar el JSON del OCR: ' + error.message +
      ' | Respuesta: ' + text
    );
  }
}

const opcion = Number(data.opcion);
if (![0, 1, 2].includes(opcion)) {
  throw new Error('El OCR devolvió una opcion inválida: ' + JSON.stringify(data.opcion));
}

data.opcion = opcion;
data.motivo_rechazo = opcion === 0
  ? (String(data.motivo_rechazo || '').trim() || 'no_es_comprobante')
  : '';

return {
  json: data,
  ...(binary ? { binary } : {})
};

const input = $input.first().json || {};

const text = String(
  input?.output?.[0]?.content?.[0]?.text ??
  input?.content?.[0]?.text ??
  input?.output_text ??
  input?.text ??
  ''
).trim();

if (!text) {
  throw new Error(
    'IA_ClasificarIntencion no devolvió texto para ParsearDatosManual. ' +
    'Estructura recibida: ' + JSON.stringify(input)
  );
}

const cedulaMatch = text.match(/cedula:\s*([0-9]{10}|[0-9]{13})/i);
const comprobanteMatch = text.match(/comprobante:\s*([^\r\n]+)/i);
const valorMatch = text.match(/valor:\s*([$€]?\s*[0-9.,]+)/i);
const fechaMatch = text.match(/fecha:\s*([0-9]{1,2}[\/.-][0-9]{1,2}[\/.-][0-9]{2,4})/i);

const datosWhatsApp = $('ExtraerDatosMensaje').first().json;
const comprobante = comprobanteMatch?.[1]?.trim() || null;

return [{
  json: {
    ...input,
    numero_whatsapp: datosWhatsApp.from || null,
    nombre_whatsapp: datosWhatsApp.name || null,
    cedula: cedulaMatch?.[1] || null,
    comprobante: comprobante && !/^N\/A$/i.test(comprobante) ? comprobante : 'N/A',
    valor: valorMatch?.[1]?.replace(/[$€\s]/g, '') || null,
    fecha: fechaMatch?.[1]?.replace(/[.-]/g, '/') || null,
    texto_clasificador: text
  }
}];

function parseMonto(valor) {
  let s = String(valor ?? '').trim().replace(/\s/g, '').replace(/[^0-9,.-]/g, '');
  if (!s) return 0;

  const ultimaComa = s.lastIndexOf(',');
  const ultimoPunto = s.lastIndexOf('.');
  if (ultimaComa > ultimoPunto) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (ultimoPunto > ultimaComa && ultimaComa !== -1) {
    s = s.replace(/,/g, '');
  } else if (ultimaComa !== -1) {
    s = s.replace(',', '.');
  }

  const numero = Number(s);
  return Number.isFinite(numero) ? numero : 0;
}

const facturasOrigen = Array.isArray($json.facturas) ? $json.facturas : [];
const facturas = facturasOrigen.filter(f => {
  const estado = String(f?.estado || '').trim().toLowerCase();
  return estado === 'no pagado' || estado === 'vencido';
});

const deudaCentavos = facturas.reduce(
  (total, factura) => total + Math.round(parseMonto(factura.total) * 100),
  0
);

return [{
  json: {
    ...$json,
    deuda_total: deudaCentavos / 100,
    deuda_centavos: deudaCentavos,
    cantidad_facturas: facturas.length,
    idcliente: facturas[0]?.idcliente || $json.idcliente || null,
    facturas
  }
}];

function parseMonto(valor) {
  let s = String(valor ?? '').trim().replace(/\s/g, '').replace(/[^0-9,.-]/g, '');
  if (!s) return null;

  const ultimaComa = s.lastIndexOf(',');
  const ultimoPunto = s.lastIndexOf('.');
  if (ultimaComa > ultimoPunto) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (ultimoPunto > ultimaComa && ultimaComa !== -1) {
    s = s.replace(/,/g, '');
  } else if (ultimaComa !== -1) {
    s = s.replace(',', '.');
  }

  const numero = Number(s);
  return Number.isFinite(numero) ? numero : null;
}

// Antes leía siempre de OCR_ParsearJSON por nombre; ese nodo no corre en
// el camino de "selección de servicio" (ejecución posterior al menú).
// Resolver_ClienteContexto ya dejó $json.monto / $json.numero_transaccion
// resueltos para ambos caminos.
const montoEsperado = parseMonto($json.monto);
const montoEsperadoCentavos = montoEsperado === null
  ? null
  : Math.round(montoEsperado * 100);

return [{
  json: {
    ...$json,
    monto_esperado: montoEsperado,
    monto_esperado_centavos: montoEsperadoCentavos,
    numero_transaccion_ocr: $json.numero_transaccion || null
  }
}];

