const fs = require('fs');
const path = require('path');

const inputItems = $input.all();
const output = [];

for (let index = 0; index < inputItems.length; index++) {
  const inputItem = inputItems[index];
  const json = inputItem.json || {};
  const binary = inputItem.binary || {};
  const rutaCompleta = String(json.ruta_completa || '').trim();

  if (!rutaCompleta) {
    throw new Error('No se recibió ruta_completa desde GenerarNombreArchivoImagen.');
  }

  const binaryNames = Object.keys(binary);
  if (binaryNames.length === 0) {
    throw new Error(
      'No se encontró información binaria en GuardarImagenEnDisco. ' +
      'Verifica Meta_DescargarImagen y GenerarNombreArchivoImagen.'
    );
  }

  const binaryName = json.binary_property && binary[json.binary_property]
    ? json.binary_property
    : (binary.data ? 'data' : binaryNames[0]);

  fs.mkdirSync(path.dirname(rutaCompleta), { recursive: true });

  // Lee el archivo mediante la API de n8n. Evita depender de rutas internas
  // como /var/lib/n8n/.n8n/binaryData o del formato filesystem-v2.
  const buffer = await this.helpers.getBinaryDataBuffer(index, binaryName);
  if (!buffer || buffer.length === 0) {
    throw new Error(`El binario '${binaryName}' está vacío.`);
  }

  fs.writeFileSync(rutaCompleta, buffer);
  const stats = fs.statSync(rutaCompleta);

  output.push({
    json: {
      ...json,
      imagen_guardada: true,
      tamanio_bytes: stats.size,
      binary_property: binaryName,
      tmp_path: null
    },
    binary
  });
}

return output;

const extractData = $('ExtraerDatosMensaje').first().json;
const descarga = $('Meta_DescargarImagen').first();
const binary = descarga.binary || {};
const binaryNames = Object.keys(binary);

if (binaryNames.length === 0) {
  throw new Error(
    'Meta_DescargarImagen no entregó datos binarios. ' +
    'Revisa que Response Format esté configurado como File.'
  );
}

const binaryName = binary.data ? 'data' : binaryNames[0];
const binaryData = binary[binaryName] || {};

const rutaBase = String($json.carpeta_destino || '').trim();
if (!rutaBase) {
  throw new Error('No se recibió carpeta_destino desde el nodo de clasificación OCR.');
}

const ahora = $now.setZone('America/Guayaquil');
const fechaArchivo = ahora.toFormat('yyyy-MM-dd_HH-mm-ss');
const limpiar = (valor, fallback) => {
  const limpio = String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-zA-Z0-9_-]/g, '_')
    .replace(/_+/g, '_')
    .replace(/^_+|_+$/g, '');
  return limpio || fallback;
};

const cedula = limpiar(extractData.cedula, 'sin_cedula');
const from = limpiar(extractData.from, 'desconocido');
const nombre = String(extractData.name || 'sin_nombre').trim();

const mime = String(binaryData.mimeType || '').toLowerCase();
const extensionMime = {
  'image/jpeg': 'jpg',
  'image/jpg': 'jpg',
  'image/png': 'png',
  'image/webp': 'webp',
  'image/gif': 'gif',
  'application/pdf': 'pdf'
};

let extension = String(binaryData.fileExtension || '').toLowerCase().replace(/[^a-z0-9]/g, '');
if (!extension) extension = extensionMime[mime] || 'bin';
if (extension === 'jpeg') extension = 'jpg';

const nombreArchivo = `${cedula}_${fechaArchivo}_${from}.${extension}`;
const rutaCompleta = `${rutaBase.replace(/\/+$/, '')}/${nombreArchivo}`;

return [{
  json: {
    ...$json,
    nombre_archivo: nombreArchivo,
    ruta_completa: rutaCompleta,
    fecha_hora: ahora.toISO(),
    fecha_hora_local: ahora.toFormat('yyyy-MM-dd HH:mm:ss'),
    zona_horaria: 'America/Guayaquil',
    from: extractData.from || null,
    nombre_contacto: nombre,
    media_id: extractData.media_id || null,
    cedula: extractData.cedula || null,
    binary_property: binaryName,
    mime_type: mime || null,
    extension_archivo: extension
  },
  binary
}];

const factura = $json.facturas?.find(f => f.estado === "No pagado" || f.estado === "vencido");

if (!factura) {
  throw new Error("No se encontró factura pendiente");
}

return {
  json: {
    idfactura: factura.id,
    cantidad: Number($json.deuda_total),
    idcliente: $json.idcliente,
    monto_pagado: $json.monto_pagado,
    monto_factura: $json.monto_factura,
    excedente: $json.excedente || 0,
    hay_excedente: $json.hay_excedente || false
  }
};

const fs = require('fs');
const path = require('path');

const wa = $('GuardarImagenEnDisco').first().json;
const ocr = $('OCR_ParsearJSON').first().json;
const FILE = wa.archivo_csv || '/home/Tlsg_n8n/registro_datos.csv';
const header = 'fecha_hora,nombre_archivo,numero_whatsapp,nombre_contacto,ruta_imagen,banco,monto,fecha_comprobante,numero_transaccion,titular,estado,cedula,media_id\n';

function csv(valor) {
  return `"${String(valor ?? '').replace(/"/g, '""')}"`;
}

fs.mkdirSync(path.dirname(FILE), { recursive: true });
if (!fs.existsSync(FILE) || fs.statSync(FILE).size === 0) {
  fs.writeFileSync(FILE, header, 'utf8');
}

const linea = [
  wa.fecha_hora,
  wa.nombre_archivo,
  wa.from,
  wa.nombre_contacto,
  wa.ruta_completa,
  ocr.banco,
  ocr.monto,
  ocr.fecha,
  ocr.numero_transaccion,
  ocr.titular,
  'recibida',
  wa.cedula,
  wa.media_id
].map(csv).join(',') + '\n';

fs.appendFileSync(FILE, linea, 'utf8');

// (Se removió la escritura a staticData.indiceTransacciones /
// firmaIndiceTransacciones: era código muerto. 'Validar Duplicados' dejó de
// leer ese caché hace tiempo -motivo documentado en su propio comentario:
// condición de carrera entre ejecuciones concurrentes- y reconstruye su
// índice leyendo los CSV directamente del disco en cada ejecución. Nada en
// el resto del workflow vuelve a leer staticData.indiceTransacciones.)

return [{
  json: {
    ...$json,
    ok: true,
    archivo_csv: FILE,
    linea_guardada: linea,
    es_legible: Boolean(wa.es_legible)
  }
}];

const wa = $('GuardarImagenEnDisco').item.json;
const archivoCsv = wa.archivo_csv;
return [{ json: { ...$json, archivo_csv_destino: archivoCsv } }];

