const input = items[0].json;

let result = {};

if (input.messages && input.messages.length > 0) {
  const message = input.messages[0];
  const image = message.image || {};
  const contact = input.contacts?.[0] || { profile: {} };

  // Extraer datos de botón interactivo
  let tipo_comprobante = null;
  let button_id = null;
  let button_title = null;

  let cedula_de_texto = null;
  if (message.type === 'text' && message.text && message.text.body) {
    const soloDigitos = message.text.body.replace(/\D/g, '');
    if (soloDigitos.length === 10 || soloDigitos.length === 13) {
      cedula_de_texto = soloDigitos;
    }
  }

  if (message.type === 'interactive') {
    const interactive = message.interactive || {};

    if (interactive.type === 'button_reply') {
      button_id = interactive.button_reply?.id || null;
      button_title = interactive.button_reply?.title || null;
      tipo_comprobante = button_id; // ← el ID del botón es el tipo_comprobante
    } else if (interactive.type === 'list_reply') {
      button_id = interactive.list_reply?.id || null;
      button_title = interactive.list_reply?.title || null;
      tipo_comprobante = button_id;
    }
  }

  result = {
    wa_message_id: message.id || null, // wamid único: clave para deduplicar reintentos del webhook de Meta
    media_id: image.id || null,
    type: message.type || null,
    cedula: image.caption || cedula_de_texto || null,
    from: message.from || null,
    name: contact.profile?.name || null,
    textbody: message.text?.body || null,
    // Nuevos campos para interactivos
    tipo_comprobante: tipo_comprobante,
    button_id: button_id,
    button_title: button_title,
    // Contexto del mensaje (reply)
    context_from: message.context?.from || null,
    context_msg_id: message.context?.id || null,
    timestamp_whatsapp: message.timestamp || null
  };

} else if (input.statuses && input.statuses.length > 0) {
  const status = input.statuses[0];
  result = {
    status: status.status,
    recipient: status.recipient_id,
    timestamp: status.timestamp,
    pricing_model: status.pricing?.pricing_model || null
  };
} else {
  result = { info: "Evento desconocido o vacío" };
}

return [{ json: result }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};
const from = $('ExtraerDatosMensaje').item.json.from;
delete staticData.conversaciones[from];
return [{ json: { ...$json, reset: true } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};
const from = $('ExtraerDatosMensaje').item.json.from;
const actual = (staticData.conversaciones[from]?.intentos_comprobante || 0) + 1;
staticData.conversaciones[from] = {
  ...(staticData.conversaciones[from] || {}),
  intentos_comprobante: actual
};
return [{ json: { ...$json, intentos_comprobante: actual } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};
const from = $('ExtraerDatosMensaje').item.json.from;
const conv = staticData.conversaciones[from] || {};
return [{ json: { ...$json, intentos_comprobante: conv.intentos_comprobante || 0 } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};

const AHORA = Date.now();
const VENTANA_MS = 24 * 60 * 60 * 1000;
for (const key of Object.keys(staticData.conversaciones)) {
  const conv = staticData.conversaciones[key];
  if (conv && conv.ultima_actividad && (AHORA - conv.ultima_actividad) > VENTANA_MS) {
    delete staticData.conversaciones[key];
  }
}

const fromRaw = $json.from || $json.recipient || null;
const from = fromRaw ? String(fromRaw).replace(/[^0-9]/g, '') : null;

const previo = (from && staticData.conversaciones[from]) ? staticData.conversaciones[from] : {};

if (from) {
  staticData.conversaciones[from] = {
    ...(staticData.conversaciones[from] || {}),
    ultima_actividad: AHORA
  };
}

return [{
  json: {
    ...$json,
    from: from,
    estado_previo: previo.estado || 'inicio',
    nombre_guardado: previo.nombre || null,
    cedula_guardada: previo.cedula || null,
    intencion_guardada: previo.intencion || null
  }
}];

