  if (ultimaComa > ultimoPunto) {
    s = s.replace(/\./g, '').replace(',', '.');
  } else if (ultimoPunto > ultimaComa && ultimaComa !== -1) {
    s = s.replace(/,/g, '');
  } else if (ultimaComa !== -1) {
    s = s.replace(',', '.');
  }

  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

const opcion = Number($json.opcion);
const banco = texto($json.banco);
const monto = parseMonto($json.monto);
const transaccion = texto($json.numero_transaccion);
const fecha = texto($json.fecha);
const titular = texto($json.titular);

// Recibe tanto opcion=1 (foto) como opcion=2 (captura) desde Switch_Intencion:
// antes existían dos nodos (Set_RutaLegible / Set_RutaNoLegible) con código
// idéntico para ambos casos, fusionados aquí. 'opcion' solo distingue el
// origen de la imagen, no su legibilidad. Se considera utilizable cuando el
// OCR obtuvo banco, monto válido y al menos una referencia verificable más.
const esLegible =
  [1, 2].includes(opcion) &&
  banco !== '' &&
  monto !== null && monto > 0 &&
  (transaccion !== '' || fecha !== '' || titular !== '');

return {
  json: {
    ...$json,
    carpeta_destino: esLegible
      ? '/home/Tlsg_n8n/whatsapp_imagenes'
      : '/home/Tlsg_n8n/whatsapp_imagenes_no_detectadas_ocr',
    archivo_csv: esLegible
      ? '/home/Tlsg_n8n/registro_datos.csv'
      : '/home/Tlsg_n8n/registro_datos_no_detectado_ocr.csv',
    es_legible: esLegible,
    motivo_ilegibilidad: esLegible
      ? ''
      : 'faltan_datos_clave_ocr'
  }
};

