const inputItem = $input.item;
const item = inputItem?.json || {};
const binary = inputItem?.binary;
const inner = Array.isArray(item) ? item[0] : item;

let text =
  inner?.['0']?.content?.[0]?.text ??
  inner?.[0]?.content?.[0]?.text ??
  inner?.content?.[0]?.text ??
  inner?.output?.[0]?.content?.[0]?.text ??
  inner?.output_text ??
  inner?.text;

if (!text) {
  throw new Error(
    'OCR_LeerComprobante no devolvió texto. Estructura recibida: ' +
    JSON.stringify(inner)
  );
}

text = String(text)
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

const inicio = text.indexOf('{');
const fin = text.lastIndexOf('}');
if (inicio === -1 || fin === -1 || fin < inicio) {
  throw new Error('La respuesta del OCR no contiene un objeto JSON válido: ' + text);
}

let data;
try {
  data = JSON.parse(text.slice(inicio, fin + 1));
} catch (error) {
  throw new Error(
    'No se pudo interpretar el JSON del OCR: ' + error.message +
    ' | Respuesta: ' + text
  );
}

const opcion = Number(data.opcion);
if (![0, 1, 2].includes(opcion)) {
  throw new Error('El OCR devolvió una opcion inválida: ' + JSON.stringify(data.opcion));
}

const motivo_rechazo = opcion === 0
  ? (String(data.motivo_rechazo || '').trim() || 'no_es_comprobante')
  : '';

return {
  json: {
    ...inner,
    ...data,
    opcion,
    motivo_rechazo
  },
  ...(binary ? { binary } : {})
};

