// Antes: devolvía solo el primer match (find). 
// Ahora: devuelve TODOS los clientes/servicios no retirados,
// porque necesitamos poder armar un menú si hay más de uno.
const datos = Array.isArray($json.datos) ? $json.datos : [];

const clientesValidos = datos.filter(
  c => c?.estado === 'ACTIVO' || c?.estado === 'SUSPENDIDO'
);

if (clientesValidos.length === 0) {
  return [];
}

// Devolvemos un único item con el array completo,
// así el siguiente nodo decide si hay 1 o varios.
return [{ json: { clientes: clientesValidos, total: clientesValidos.length } }];

// Rama TRUE de IF_MultiplesServicios: el cliente tiene varios contratos/servicios.
// Armamos las filas del menú interactivo (máx 10 filas por WhatsApp).
const clientes = $('FiltrarClienteRetirado').item.json.clientes.slice(0, 10);

function resumenDireccion(direccion) {
  if (!direccion) return 'Sin dirección registrada';
  const limpio = direccion.trim();
  return limpio.length > 60 ? limpio.slice(0, 57) + '...' : limpio;
}

const rows = clientes.map((c, i) => ({
  id: `serv_${c.codigo}`,
  title: `${i + 1}. ${c.estado === 'ACTIVO' ? '🟢' : '🟡'} ${c.nombre}`.slice(0, 24),
  description: resumenDireccion(c.direccion_principal)
}));

return [{
  json: {
    rows,
    clientes_originales: clientes,
    cedula: clientes[0]?.cedula || ''
  }
}];

