parameters.jsCode:
// Esta rama corre en una EJECUCIÓN NUEVA: el disparador es el clic del
// usuario sobre la lista de servicios (interactive.list_reply).
// Antes esto se leía SOLO de staticData (memoria RAM compartida sin lock),
// lo que causaba condiciones de carrera con ejecuciones paralelas (dobles
// webhooks de Meta, doble-tap, etc). Ahora la fuente de verdad es Postgres
// (nodo 'DB_Leer_SesionParaSeleccion', corrido justo antes que este, que hace
// JOIN sesiones -> comprobantes vía el FK comprobante_id), y staticData
// queda solo como respaldo si la fila aún no existe en BD.

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};

const from = $('ExtraerDatosMensaje').item.json.from;
const conv = staticData.conversaciones[from] || {};

// Fila devuelta por DB_Leer_SesionParaSeleccion (sesiones + comprobantes por JOIN)
const dbRow = $json || {};

function safeParse(val, fallback) {
  if (val == null) return fallback;
  if (typeof val === 'object') return val; // jsonb: node-postgres ya lo entrega parseado
  try { return JSON.parse(val); } catch (e) { return fallback; }
}

const serviciosGuardados = (dbRow.servicios_disponibles != null)
  ? safeParse(dbRow.servicios_disponibles, [])
  : (conv.servicios_disponibles || []);

const menuGeneradoEn = dbRow.menu_generado_en
  ? Number(dbRow.menu_generado_en)
  : (conv.menu_generado_en || null);

const sesionId = dbRow.sesion_id || conv.sesion_id || null;

// Comprobante: viene "aplanado" por el JOIN a comprobantes. Si no hay
// comprobante_id todavía en BD, caemos al respaldo de staticData.
const comprobanteDeBD = dbRow.numero_transaccion ? {
  numero_transaccion: dbRow.numero_transaccion,
  banco: dbRow.banco || null,
  monto: dbRow.monto || null,
  fecha_comprobante: dbRow.fecha_comprobante || null,
  titular: dbRow.titular || null,
  ruta_imagen: dbRow.ruta_imagen || null,
  media_id: dbRow.media_id || null,
  id: dbRow.comprobante_id || null
} : null;

const comprobante = comprobanteDeBD || conv.comprobante || null;

const listReplyId = $('ExtraerDatosMensaje').item.json.button_id || ''; // 'serv_<codigo>'
const codigoSeleccionado = listReplyId.replace('serv_', '');

const EXPIRACION_MS = 15 * 60 * 1000; // 15 minutos para elegir el servicio
const expirado = menuGeneradoEn
  ? (Date.now() - menuGeneradoEn) > EXPIRACION_MS
  : false;

const clienteElegido = serviciosGuardados.find(c => String(c.codigo) === codigoSeleccionado);

if (expirado) {
  return [{ json: { error: true, expirado: true,
    mensaje: 'El menú de servicios expiró. Por favor envía de nuevo tu cédula junto con el comprobante de pago.' } }];
}

if (!clienteElegido) {
  return [{ json: { error: true,
    mensaje: 'No se encontró el servicio seleccionado, por favor intenta de nuevo.' } }];
}

if (!comprobante || !comprobante.numero_transaccion) {
  return [{ json: { error: true, sin_comprobante: true,
    mensaje: 'No encontramos tu comprobante de pago, por favor envíalo nuevamente junto con tu cédula.' } }];
}

return [{
  json: {
    ...clienteElegido,                       // id, codigo, cedula, nombre, estado, direccion_principal...
    sesion_id: sesionId,
    numero_transaccion: comprobante.numero_transaccion,
    banco: comprobante.banco || null,
    monto: comprobante.monto || null,
    fecha_comprobante: comprobante.fecha_comprobante || null,
    titular: comprobante.titular || null,
    ruta_imagen: comprobante.ruta_imagen || null,
    media_id: comprobante.media_id || null,
    comprobante_id: comprobante.id || null,
    fue_multiples_servicios: true,
    codigo_servicio_elegido: codigoSeleccionado
  }
}];

// Rama FALSE de IF_MultiplesServicios: solo hay 1 servicio,
// seguimos igual que antes (flujo normal, sin menú).
// Se referencia FiltrarClienteRetirado por nombre porque IF_MultiplesServicios
// ahora se evalúa después del pipeline de descarga/OCR del comprobante,
// no inmediatamente después.
return [{ json: $('FiltrarClienteRetirado').item.json.clientes[0] }];

// Punto de convergencia entre el flujo de "cliente único" (todo ocurre en
// la misma ejecución que recibió el comprobante) y el de "selección de
// servicio" (ejecución posterior, disparada por el clic en la lista).
// A partir de aquí, TODO el flujo de activación usa exclusivamente los
// campos de este nodo (no vuelve a asumir qué nodo corrió antes).

function tryGet(nodeName, path) {
  try {
    const j = $(nodeName).item.json;
    return path.split('.').reduce((o, k) => (o == null ? undefined : o[k]), j);
  } catch (e) {
    return undefined;
  }
}

const idcliente = $json.id ?? tryGet('ClienteUnico', 'id') ?? tryGet('GuardarSeleccionServicio', 'id') ?? null;
const codigo_servicio = $json.codigo ?? tryGet('ClienteUnico', 'codigo') ?? tryGet('GuardarSeleccionServicio', 'codigo') ?? null;

const numero_transaccion = $json.numero_transaccion
  ?? tryGet('OCR_ParsearJSON', 'numero_transaccion')
  ?? tryGet('GuardarSeleccionServicio', 'numero_transaccion')
  ?? tryGet('Usar_ComprobanteGuardado', 'numero_transaccion')
  ?? null;

const monto = $json.monto
  ?? tryGet('OCR_ParsearJSON', 'monto')
  ?? tryGet('GuardarSeleccionServicio', 'monto')
  ?? tryGet('Usar_ComprobanteGuardado', 'monto')
  ?? null;

const cedula = tryGet('ExtraerDatosMensaje', 'cedula')
  ?? tryGet('GuardarSeleccionServicio', 'cedula')
  ?? $json.cedula
  ?? null;

const sesion_id = tryGet('Sesion_GestionarID', 'sesion_id')
  ?? tryGet('GuardarSeleccionServicio', 'sesion_id')
  ?? null;

const estado_conversacion = tryGet('LeerEstadoConversacion', 'estado_previo') ?? null;
const duplicado = tryGet('Validar Duplicados', 'duplicado') ?? false;
const opcion_ocr = tryGet('OCR_PrepararDatosParaSwitch', 'opcion') ?? null;
const comprobante_id = tryGet('GuardarSeleccionServicio', 'comprobante_id') ?? tryGet('Usar_ComprobanteGuardado', 'comprobante_id') ?? null;
const fue_multiples_servicios = tryGet('GuardarSeleccionServicio', 'fue_multiples_servicios') ?? false;

return [{
  json: {
    ...$json,
    idcliente,
    codigo_servicio,
    numero_transaccion,
    monto,
    cedula,
    sesion_id,
    estado_conversacion,
    duplicado,
    opcion_ocr,
    comprobante_id,
    fue_multiples_servicios
  }
}];

// OCR_GetFacturas es un nodo HTTP: su salida reemplaza $json con la
// respuesta cruda de la API y pierde el contexto de Resolver_ClienteContexto.
// Lo reintegramos aquí para que el resto del flujo (deuda, monto, logs)
// tenga todo disponible sin depender de nodos que no corrieron en esta ejecución.
const ctx = $('Resolver_ClienteContexto').item.json;

return [{
  json: {
    ...$json,
    idcliente: ctx.idcliente,
    codigo_servicio: ctx.codigo_servicio,
    numero_transaccion: ctx.numero_transaccion,
    monto: ctx.monto,
    cedula: ctx.cedula,
    sesion_id: ctx.sesion_id,
    estado_conversacion: ctx.estado_conversacion,
    duplicado: ctx.duplicado,
    opcion_ocr: ctx.opcion_ocr,
    comprobante_id: ctx.comprobante_id,
    fue_multiples_servicios: ctx.fue_multiples_servicios
  }
}];

// Corre apenas el comprobante fue descargado, leído por OCR y registrado
// en la tabla `comprobantes` (CSV_RegistrarTransaccion1 / DB_CSV_RegistrarTransaccion1).
// Deja todo listo en staticData por si el cliente tiene varios servicios y
// hace falta esperar una segunda interacción (clic en la lista) para saber
// a cuál aplicar este comprobante — sin pedirlo de nuevo.
const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};

const from = $('ExtraerDatosMensaje').item.json.from;
const sesionId = $('Sesion_GestionarID').item.json.sesion_id;
const ocr = $('OCR_ParsearJSON').item.json;
const archivo = $('GuardarImagenEnDisco').item.json;

const comprobante = {
  numero_transaccion: ocr.numero_transaccion || null,
  banco: ocr.banco || null,
  monto: ocr.monto || null,
  fecha_comprobante: ocr.fecha || null,
  titular: ocr.titular || null,
  ruta_imagen: archivo.ruta_completa || null,
  media_id: archivo.media_id || null,
  cedula: archivo.cedula || null,
  id: $json.id || null   // id devuelto por DB_CSV_RegistrarTransaccion1, si corrió antes de este nodo
};

staticData.conversaciones[from] = {
  ...(staticData.conversaciones[from] || {}),
  sesion_id: sesionId,
  comprobante,
  ultima_actividad: Date.now()
};

// Se agrega 'comprobante' y 'sesion_id' al output (antes pasaba $json intacto)
// para que el nuevo nodo DB_Guardar_ComprobanteEnSesion pueda persistirlo en Postgres.
return [{ json: { ...$json, comprobante, sesion_id: sesionId } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};

const from = $('ExtraerDatosMensaje').item.json.from;

staticData.conversaciones[from] = {
  ...(staticData.conversaciones[from] || {}),
  es_multiples_servicios: true,
  servicios_disponibles: $json.clientes_originales || [],
  menu_generado_en: Date.now(),
  ultima_actividad: Date.now()
};

return [{ json: $json }]; // pasa intacto a Send_MenuServicios

// Meta reenvía el webhook si no recibe 200 OK a tiempo, y a veces el usuario
// también puede generar un doble evento (doble tap sobre el mismo botón/fila).
// Ademas, se detectó que un doble-tap puede llegar con un wa_message_id DISTINTO
// (no es un reintento exacto de Meta), por lo que el chequeo original por ID
// no lo atrapaba y terminaba disparando una segunda ejecución fantasma que caía
// en el clasificador de IA y respondía "No pude identificar tu solicitud".
// Ahora también deduplicamos por combinación (from + button_id) en una ventana corta.

const staticData = $getWorkflowStaticData('global');
if (!staticData.mensajesProcesados) staticData.mensajesProcesados = {};
if (!staticData.botonesProcesados) staticData.botonesProcesados = {};

const TTL_MS = 10 * 60 * 1000; // 10 minutos para reintentos de Meta por wa_message_id
const TTL_BOTON_MS = 8 * 1000; // 8 segundos para doble-tap del mismo botón
const ahora = Date.now();
const waId = $json.wa_message_id;
const from = $json.from || '';
const buttonId = $json.button_id || '';

// limpieza perezosa de entradas viejas para no acumular memoria indefinidamente
for (const id in staticData.mensajesProcesados) {
  if (ahora - staticData.mensajesProcesados[id] > TTL_MS) {
    delete staticData.mensajesProcesados[id];
  }
}
for (const key in staticData.botonesProcesados) {
  if (ahora - staticData.botonesProcesados[key] > TTL_BOTON_MS) {
    delete staticData.botonesProcesados[key];
  }
}

// los eventos de status (sin wa_message_id propio de un mensaje entrante) no se deduplican aquí
if (!waId) {
  return [{ json: { ...$json, es_duplicado: false } }];
}

const yaProcesadoPorId = !!staticData.mensajesProcesados[waId];
staticData.mensajesProcesados[waId] = ahora;

let yaProcesadoPorBoton = false;
if (buttonId) {
  const claveBoton = `${from}::${buttonId}`;
  yaProcesadoPorBoton = !!staticData.botonesProcesados[claveBoton];
  staticData.botonesProcesados[claveBoton] = ahora;
}

const esDuplicado = yaProcesadoPorId || yaProcesadoPorBoton;

return [{ json: { ...$json, es_duplicado: esDuplicado } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};
const from = $('ExtraerDatosMensaje').item.json.from;
const cedula = $json.cedula || $('ExtraerDatosMensaje').item.json.cedula;

staticData.conversaciones[from] = {
  ...(staticData.conversaciones[from] || {}),
  cedula: cedula,
  estado: 'esperando_comprobante'
};

return [{ json: { ...$json, cedula_final: cedula } }];

// Une la cedula que llega en ESTE mensaje con la que ya estaba guardada
// de una interaccion anterior. Asi funciona sin importar el orden.
const cedulaMensaje = $('ExtraerDatosMensaje').item.json.cedula;
let cedulaGuardada = null;
try { cedulaGuardada = $('LeerEstadoConversacion').item.json.cedula_guardada; } catch (e) {}
const cedula_final = cedulaMensaje || cedulaGuardada || null;

return [{ json: { ...$json, cedula_final } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};
const from = $('ExtraerDatosMensaje').item.json.from;
let cedulaValidada = null;
try { cedulaValidada = $('Resolver_CedulaActiva').item.json.cedula_final; } catch (e) {}

staticData.conversaciones[from] = {
  ...(staticData.conversaciones[from] || {}),
  cedula: cedulaValidada,
  estado: 'esperando_comprobante'
};

return [{ json: $json }];

// El cliente ya fue validado en ESTA misma ejecucion? (la cedula llego antes que la imagen)
let resuelto = false;
try {
  resuelto = !!$('Log_CedulaValida').item;
} catch (e) {
  resuelto = false;
}
return [{ json: { ...$json, cliente_resuelto: resuelto } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.conversaciones) staticData.conversaciones = {};
const from = $('ExtraerDatosMensaje').item.json.from;

staticData.conversaciones[from] = {
  ...(staticData.conversaciones[from] || {}),
  estado: 'esperando_cedula'
};

return [{ json: $json }];

// Reinyecta el comprobante que ya se habia guardado en un mensaje anterior,
// para que el resto del flujo (deuda, activacion) siga sin volver a pedirlo
// ni a reprocesar la imagen.
return [{
  json: {
    ...$json,
    numero_transaccion: $json.numero_transaccion,
    monto: $json.monto,
    banco: $json.banco,
    fecha: $json.fecha_comprobante,
    titular: $json.titular,
    comprobante_id: $json.comprobante_id_real || $json.comprobante_id
  }
}];

const deuda = Number($json.deuda_total) || 0;
const pagado = Number($json.monto_esperado) || 0;
let excedente = Math.round((pagado - deuda) * 100) / 100;
if (excedente < 0) excedente = 0;
return [{
  json: {
    ...$json,
    monto_pagado: pagado,
    monto_factura: deuda,
    excedente,
    hay_excedente: excedente > 0
  }
}];

const items = $input.first().json.datos || [];

// 1) Si tenemos el id/codigo del servicio reactivado, usarlo como match exacto
const codigoReactivado = $('Resolver_ClienteContexto').item.json.codigo; // ajusta el nombre real del campo si existe

let clienteFinal = null;

if (codigoReactivado) {
  clienteFinal = items.find(c => c.codigo === codigoReactivado);
}

// 2) Si no hay match exacto, priorizar el que esté ACTIVO
if (!clienteFinal) {
  const activos = items.filter(c => c.estado === 'ACTIVO');
  if (activos.length === 1) {
    clienteFinal = activos[0];
  } else if (activos.length > 1) {
    // 3) Si hay varios activos, el de fecha_suspendido más reciente
    clienteFinal = activos.sort((a, b) =>
      new Date(b.fecha_suspendido) - new Date(a.fecha_suspendido)
    )[0];
  }
}

// 4) Fallback: si nada calzó, usar el primero (comportamiento anterior)
if (!clienteFinal) {
  clienteFinal = items[0] || {};
}

return [{
  json: {
    ...$input.first().json,
    clienteFinal
  },
  binary: $input.first().binary
}];

const fs = require('fs');

// Ajusta esta ruta a donde tienes guardada la imagen de la guía en el servidor
const rutaImagen = '/home/Tlsg_n8n/imagenes/guia_reactivacion.png';

const buffer = fs.readFileSync(rutaImagen);

const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  'comprobante_guia.png',
  'image/png'
);

return [
  {
    json: $input.first().json,
    binary: {
      data: binaryData
    }
  }
];
